// Structural primitives over the grammar AST (RuleExpr), shared by the parser
// generator (gen-parser) and the TextMate highlighter generator (gen-tm).
//
// Only PURE, structural helpers belong here — the small things both consumers
// build on. The high-level logic stays separate: gen-parser's parse strategy
// (FIRST sets, left-recursion, Pratt classification) answers "how to parse";
// gen-tm's shape detection answers "how to emit TextMate regexes". Those change
// for different reasons and must not be coupled.
import type { RuleExpr } from './types.ts';

/** True if `code` is an identifier-start character: a-z, A-Z, `_`, or `$`. */
export function isIdentStartCode(code: number): boolean {
  return (code >= 97 && code <= 122) || (code >= 65 && code <= 90) || code === 95 || code === 36;
}

/**
 * Classify a grammar literal as a keyword/identifier-word (`new`, `readonly`, …)
 * vs punctuation (`=>`, `+`, `(`, …). Decided by the first character: every
 * literal/operator in the grammar is either identifier-shaped or starts with
 * punctuation, so the first char discriminates (verified: 0 divergence from a
 * full all-characters check across all 144 literals/operators/token names).
 *
 * charCode-based, NO regex — this runs in the parse hot path (matchLiteral,
 * keyMatchesTok), where a regex-per-call measurably regressed throughput.
 *
 * Single source of truth so the parser and the highlighter classify keywords
 * IDENTICALLY — the project's "single grammar → parser + highlighter, never
 * disagree" invariant would be violated by two private predicates.
 *
 * `@`-headed word literals (`@new`) are keyword-class too: a keyword literal
 * matches a NAMED token by exact text (matchLiteral's keyword branch), which is
 * exactly what a fused decorator-head token (`@new` lexed as one Decorator
 * token) needs — it can never be punctuation. A bare `@` stays punctuation.
 */
export function isKeywordLiteral(s: string): boolean {
  return isIdentStartCode(s.charCodeAt(0)) || (s.charCodeAt(0) === 64 && isIdentStartCode(s.charCodeAt(1)));
}

/** Every literal string reachable in a rule expression (incl. `sep` delimiters). */
export function collectLiterals(expr: RuleExpr): string[] {
  switch (expr.type) {
    case 'literal': return [expr.value];
    case 'seq': case 'alt': return expr.items.flatMap(collectLiterals);
    case 'quantifier': case 'group': return collectLiterals(expr.body);
    case 'sep': return [...collectLiterals(expr.element), expr.delimiter];
    default: return [];
  }
}

// The createLexer runtime as SOURCE TEXT, for emitted parsers whose grammar has no specialized
// lexer (indent / newline / markup state machines stay data-driven — see emit-lexer.ts). The
// emitted module carries this text instead of importing it, so it loads with no dependency on
// monogram and no path baked in from the machine that emitted it.
//
// The sources stay the single copy: the closure is computed by following gen-lexer.ts's
// relative imports, and every file is included verbatim minus its module syntax. Anything the
// transform cannot carry faithfully (a non-relative import, a re-export, `export default`,
// `import.meta`, a top-level name declared by two files) throws at emit time instead of
// producing a module that breaks at load time.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve, basename } from 'node:path';

const SRC_DIR = dirname(fileURLToPath(import.meta.url));
const ENTRY = 'gen-lexer.ts';

const IMPORT_DECL = /^import\s+(?:type\s+)?\{[^}]*\}\s+from\s+'([^']+)';[ \t]*$/gm;
const EXPORT_DECL = /^export\s+(?=(?:declare\s+)?(?:async\s+)?(?:function|const|let|class|interface|type|enum|abstract\s+class)\b)/gm;
const TOP_LEVEL_NAME = /^(?:export\s+)?(?:declare\s+)?(?:async\s+)?(?:function\*?|const|let|var|class|interface|type|enum|abstract\s+class)\s+([A-Za-z_$][\w$]*)/gm;

interface RuntimeFile { name: string; body: string; deps: string[] }

function readRuntimeFile(name: string): RuntimeFile {
  const text = readFileSync(resolve(SRC_DIR, name), 'utf8');
  const deps: string[] = [];
  const body = text.replace(IMPORT_DECL, (_m, spec: string) => {
    if (!spec.startsWith('./') || spec.includes('/', 2)) throw new Error(`inline runtime: src/${name} imports ${JSON.stringify(spec)} — only sibling modules can be inlined`);
    deps.push(basename(spec));
    return '';
  }).replace(EXPORT_DECL, '');
  for (const [re, what] of [[/^\s*import\b/m, 'an import'], [/^\s*export\b/m, 'an export'], [/\bimport\.meta\b|\brequire\s*\(|(?:[=(,]|\bawait|\breturn)\s*import\s*\(/, 'a dynamic module reference']] as const) {
    if (re.test(body)) throw new Error(`inline runtime: src/${name} still has ${what} after the transform — extend inline-runtime.ts or restructure the source`);
  }
  return { name, body, deps };
}

// Dependencies first, so every declaration precedes the code that names it at load time.
function runtimeClosure(): RuntimeFile[] {
  const order: RuntimeFile[] = [];
  const seen = new Set<string>();
  const visit = (name: string) => {
    if (seen.has(name)) return;
    seen.add(name);
    const file = readRuntimeFile(name);
    for (const d of file.deps) visit(d);
    order.push(file);
  };
  visit(ENTRY);
  return order;
}

/** The runtime closure as one block that binds a module-local `createLexer` and nothing else. */
export function inlineLexerRuntime(): string {
  const files = runtimeClosure();
  const owner = new Map<string, string>();
  for (const f of files) {
    for (const m of f.body.matchAll(TOP_LEVEL_NAME)) {
      const prev = owner.get(m[1]);
      if (prev !== undefined && prev !== f.name) throw new Error(`inline runtime: top-level name ${m[1]} is declared in both src/${prev} and src/${f.name}`);
      owner.set(m[1], f.name);
    }
  }
  return [
    `// ── createLexer runtime (inlined from monogram ${files.map(f => 'src/' + f.name).join(', ')}) ──`,
    `const createLexer = (() => {`,
    ...files.map(f => `// ── src/${f.name} ──\n${f.body}`),
    `return createLexer;`,
    `})();`,
  ].join('\n');
}

/**
 * Target-neutral data contracts for generated shape recognizers.
 *
 * This module deliberately contains no target runtime. TS, Rust, and Go emitters
 * can share these identities and transaction rules without sharing codegen.
 */

/** Identity path through RD alternatives, nested inline alternatives, and Pratt events. */
export type AltPathPart =
  | { kind: 'rd'; rule: string; alt: number }
  | { kind: 'inline-alt'; branch: number }
  | { kind: 'pratt-nud'; event: 'atom' | 'group' | 'prefix' | 'nudSeq' | 'nudCapped'; index: number }
  | { kind: 'pratt-led'; event: 'binary' | 'postfix' | 'postfixTok' | 'led'; index: number };
export type AltPath = readonly AltPathPart[];

/** A visible value channel. Optional holes retain position instead of disappearing. */
export type VisibleSlot<H = unknown> =
  | { kind: 'slot'; value: H }
  | { kind: 'list'; values: H[] }
  | { kind: 'hole'; value: H | null };

export type PrattEvent<H = unknown> =
  | { kind: 'atom'; value: H }
  | { kind: 'group'; value: H }
  | { kind: 'prefix'; operator: string; argument: H }
  | { kind: 'binary'; left: H; operator: string; right: H }
  | { kind: 'postfix'; left: H; operator: string }
  | { kind: 'postfixTok'; left: H; token: H }
  | { kind: 'led'; left: H; slots: readonly VisibleSlot<H>[] }
  | { kind: 'nudSeq'; slots: readonly VisibleSlot<H>[] }
  | { kind: 'nudCapped'; slots: readonly VisibleSlot<H>[] }
  /** Template product: kids are head, expr, optional middle/expr pairs, and tail — or a lone no-subst leaf. */
  | { kind: 'template'; slots: readonly VisibleSlot<H>[] };

/** Length snapshots are valid only for append-only channels. */
export type AppendOnlyCheckpoint = {
  pos: number;
  kidsLength: number;
  listsLength: number;
  holesLength: number;
  altPathLength: number;
};

/** Prior value for a slot overwritten during a speculative transaction. */
export type UndoEntry<H = unknown> = {
  channel: 'slot' | 'state';
  index: number;
  previous: H;
};

export type ShapeTransaction<H = unknown> = {
  checkpoint: AppendOnlyCheckpoint;
  undo: UndoEntry<H>[];
  status: 'open' | 'committed' | 'rolledBack';
};

/**
 * Transaction contract:
 * - append-only arrays roll back by restoring their checkpointed lengths;
 * - overwrites must be recorded in `undo`, or staged and applied only on commit;
 * - parser position and every mutable Pratt/control flag (`_suppressNext` /
 *   `_suppressCur` / capped) join the same transaction;
 * - function-local `left`/`opText` values need no log when assigned only after success.
 */
export const SHAPE_TRANSACTION_CONTRACT = {
  appendOnly: 'restore-lengths',
  overwrite: 'undo-log-or-commit-on-success',
  prattLocals: 'commit-on-success',
  controlFlags: 'restore-with-checkpoint',
} as const;

/**
 * Local custom context, populated only after the recognizer has successfully
 * finished the current rule/Pratt event.
 *
 * `kids` preserves star/sep groups as arrays and absent optional values as
 * null holes. `off`/`end` cover the consumed source range. `altPath` is filled
 * outermost-first with the selected RD/Pratt arm followed by nested inline
 * alternatives. Pratt LED callbacks additionally receive the committed
 * `left` value and connector `opText`. `state` is present only when the
 * enclosing shape explicitly declares a parent fold.
 */
export type AstCustomCtx = {
  src: string;
  kids: readonly unknown[];
  altPath: readonly number[];
  off: number;
  end: number;
  opText?: string;
  left?: unknown;
  state?: unknown;
};
export type AstCustom = (ctx: AstCustomCtx) => unknown;

/**
 * Consumer-facing declarative AST shape schema and normalized codegen IR.
 */

export type FieldBind =
  | { at: number }
  | { label: string }
  | { from: 'list'; of: number | 'rest' }
  | { from: 'opt'; at: number }
  | 'opText';

export type FieldDecl = {
  name: string;
  bind: FieldBind;
  optional?: boolean;
  typeHint?: string | string[];
};

export type NodeShape = {
  kind: 'node';
  type: string;
  fields: FieldDecl[];
  exact?: boolean;
};

export type ListShape = { kind: 'list'; field: string; elemHint?: string };
export type InlineShape = { kind: 'inline' };
export type DropShape = { kind: 'drop' };
export type LeafValueShape = {
  kind: 'leafValue';
  fn: 'identity' | 'number' | 'bigint' | 'string' | 'boolean' | 'ident' | (string & {});
};
/**
 * Generic child-partial fold. A partial-producing custom returns
 * `{ __shapePartial: tag, mode: 'start'|'append', value }`. At parent finish,
 * matching groups are folded before the parent's custom callback runs:
 * `start` opens an output item and `append` pushes into that item's `into`
 * array. No grammar/rule name is embedded in the mechanism.
 */
export type ParentFold = { tag: string; into: string };
/**
 * M-A1.4-S2: streaming estree type for one arm of a custom node. String = fixed
 * estree type; the three object forms are runtime/dynamic decisions that the
 * generated type table resolves at event time:
 *  - passthrough: type of the first kid (TNode → its node type, Str → Identifier)
 *  - optionalChain: kids[0] is a list → CallExpression, else MemberExpression
 *  - parenOrComma: arm 7 → MetaProperty; 1 kid → its type; else SequenceExpression
 */
export type StreamType =
  | string
  | { passthrough: true }
  | { optionalChain: true }
  | { parenOrComma: true };
export type CustomShape = {
  kind: 'custom';
  fn: string;
  reason: string;
  result?: 'value' | 'partial';
  folds?: ParentFold[];
  /** M-A1.4-S2: per-arm streaming estree types, index = reachable arm. */
  types?: StreamType[];
  /** M-A1.4-S2: op→estree-type table for op-driven customs (binary/prefix). */
  opMap?: Record<string, string>;
};
export type KeepShape = { kind: 'keep' };
/** Delegate Pratt atom NUD to an RD rule (e.g. Atom choice → Number|Identifier nodes). */
export type RuleRefShape = { kind: 'rule'; name: string };

export type ChoiceArm = {
  name: string;
  altIndices: number[];
  shape: Exclude<RuleShape, ChoiceShape>;
};
export type ChoiceShape = { kind: 'choice'; arms: ChoiceArm[] };

export type PrattShape = {
  kind: 'pratt';
  atom?: LeafValueShape | KeepShape | DropShape | CustomShape | RuleRefShape;
  /** Unmapped IR brackets default to keep (positional node). */
  group?: InlineShape | NodeShape | CustomShape | KeepShape;
  nudSeq?: RuleShapeAtom;
  nudCapped?: RuleShapeAtom;
  prefix?: NodeShape | CustomShape | InlineShape | KeepShape;
  binary?: NodeShape | CustomShape | KeepShape;
  postfix?: NodeShape | CustomShape | KeepShape | InlineShape;
  led?: RuleShapeAtom;
  postfixTok?: RuleShapeAtom;
  /**
   * Template literal product (subst `$templateHead`… or no-subst Template leaf).
   * Not a new primitive — only custom|keep. Omitted → legacy `$template` keep with
   * portable interpRule holes (CST-parity accept set). Declared → kids are
   * head, expr, optional middle/expr pairs, then tail (or `[leaf]` for no-subst)
   * finished by this slot; hole accept still uses portable interpRule, hole AST
   * uses enclosing Pratt.
   */
  template?: CustomShape | KeepShape;
};

export type RuleShapeAtom =
  | NodeShape | ListShape | InlineShape | DropShape
  | LeafValueShape | CustomShape | KeepShape | PrattShape;
export type RuleShape = RuleShapeAtom | ChoiceShape;

export type TokenLeafPolicy =
  | { action: 'drop' }
  | { action: 'keep' }
  | { action: 'leafValue'; fn: LeafValueShape['fn'] };

export type ShapeSpec = {
  grammar: string;
  spans: 'required' | 'optional' | 'none';
  unmapped: 'default' | 'error';
  leaves: Record<string, TokenLeafPolicy>;
  rules: Record<string, RuleShape>;
};

export type ShapeIRRule = {
  name: string;
  cstName: string;
  kind: 'rd' | 'pratt';
  source: 'exact' | 'cstName' | 'default';
  shape: RuleShape;
};
export type ShapeIR = {
  grammar: string;
  spans: ShapeSpec['spans'];
  leaves: ShapeSpec['leaves'];
  rules: ShapeIRRule[];
  diagnostics: ShapeDiag[];
};
export type ShapeDiag = {
  level: 'error' | 'warn' | 'info';
  rule?: string;
  code: string;
  message: string;
};

