import { writeFileSync, mkdirSync } from 'node:fs';
import { basename, dirname, join, resolve } from 'node:path';
import { generateTmLanguage, generateMarkupInjection, generateAliasGrammar, generateContributes } from './gen-tm.ts';
import { generateLanguageConfig } from './gen-vscode-config.ts';
import { generateTreeSitter } from './gen-treesitter.ts';
import { generateMonarch } from './gen-monarch.ts';
import { generateCstMatch } from './gen-cst-match.ts';
import type { CstGrammar, RuleExpr } from './types.ts';
import { tokenPatternSource } from './token-pattern.ts';

const file = process.argv[2];
if (!file) {
  console.error('Usage: tsx src/cli.ts <grammar.ts>');
  process.exit(1);
}

const mod = await import(resolve(file));
const grammar = mod.default as CstGrammar & { name?: string };
// An unnamed grammar takes its name from the filename; set it on the grammar so the generators
// have one source of truth (gen-tm reads `grammar.name` rather than taking a name parameter).
const langName = grammar.name ?? basename(file, '.ts');
grammar.name = langName;

console.log(`Parsed ${file}:`);
console.log(`  ${grammar.tokens.length} tokens`);
console.log(`  ${grammar.precs.length} precedence levels`);
console.log(`  ${grammar.rules.length} rules`);
console.log();

// Dump parsed model
console.log('── Tokens ──');
for (const t of grammar.tokens) {
  const flags = t.flags.length > 0 ? `  @${t.flags.join(' @')}` : '';
  console.log(`  ${t.name}: /${tokenPatternSource(t)}/${flags}`);
}

console.log('\n── Precedence ──');
for (const p of grammar.precs) {
  const ops = p.operators.map(o => {
    const pos = o.position !== 'infix' ? `${o.position} ` : '';
    return `${pos}'${o.value}'`;
  }).join(' ');
  console.log(`  ${p.assoc}: ${ops}`);
}

console.log('\n── Rules ──');
for (const r of grammar.rules) {
  console.log(`  ${r.name} = ${formatExpr(r.body)}`);
}

// Generate TextMate grammar
const tm = generateTmLanguage(grammar);
const outPath = join(dirname(file), `${langName}.tmLanguage.json`);
writeFileSync(outPath, JSON.stringify(tm, null, 2) + '\n');
console.log(`\n→ Generated ${outPath}`);

// Markup-injection grammars (Vue directives + interpolation), when the grammar declares
// `markup.inject` — one THIN-STUB file per concern, injected onto the host (HTML) scopes,
// matching the official Vue topology (vue-directives.json / vue-interpolations.json). The
// rule bodies live in the main grammar's repository; these files just include them.
for (const injection of generateMarkupInjection(grammar)) {
  const injPath = join(dirname(file), `${injection.scopeName}.tmLanguage.json`);
  writeFileSync(injPath, JSON.stringify(injection, null, 2) + '\n');
  console.log(`→ Generated ${injPath}`);
}

// Alias grammars — extra files that re-expose this grammar under another scopeName (e.g.
// text.html.derivative for embedded HTML fragments). One thin `{scopeName, include}` file each.
for (const alias of grammar.aliasScopes ?? []) {
  const aliasGrammar = generateAliasGrammar(grammar.scopeName ?? `source.${langName}`, alias.scope);
  const aliasPath = join(dirname(file), `${alias.file}.tmLanguage.json`);
  writeFileSync(aliasPath, JSON.stringify(aliasGrammar, null, 2) + '\n');
  console.log(`→ Generated ${aliasPath}`);
}

// A VS Code `contributes` snippet — packaging that wires all the generated grammars (main +
// injections + aliases) into an editor. For Vue this is what makes the files a drop-in for
// vuejs/language-tools'; emitted only when the grammar declares a `manifest`.
const contributes = generateContributes(grammar);
if (contributes) {
  const cPath = join(dirname(file), `${langName}.contributes.json`);
  writeFileSync(cPath, JSON.stringify({ contributes }, null, 2) + '\n');
  console.log(`→ Generated ${cPath}`);
}

// Generate VS Code language configuration (editor behaviors)
const langConfig = generateLanguageConfig(grammar);
const cfgPath = join(dirname(file), `${langName}.language-configuration.json`);
writeFileSync(cfgPath, JSON.stringify(langConfig, null, 2) + '\n');
console.log(`→ Generated ${cfgPath}`);

// ── Parser-ecosystem + type targets (one grammar → every ecosystem) ──
const emit = (rel: string, content: string) => {
  const full = join(dirname(file), rel);
  mkdirSync(dirname(full), { recursive: true });
  writeFileSync(full, content.endsWith('\n') ? content : content + '\n');
  console.log(`→ Generated ${full}`);
};

// tree-sitter: grammar.js + highlight queries + (optionally) an external scanner.
// Namespaced under tree-sitter/<name>/ so multiple grammars coexist (a tree-sitter
// package keeps grammar.js + queries/ + src/ together). Markup grammars get a
// purpose-built grammar with NO external tokens (v1), so no scanner.c is emitted.
const treeSitter = generateTreeSitter(grammar, langName);
emit(`tree-sitter/${langName}/grammar.js`, treeSitter.grammarJs);
emit(`tree-sitter/${langName}/queries/highlights.scm`, treeSitter.highlightsScm);
if (treeSitter.scannerC.trim()) emit(`tree-sitter/${langName}/src/scanner.c`, treeSitter.scannerC);
// A package.json so `tree-sitter generate`/`build` can load grammar.js as CommonJS
// (the repo root is "type":"module", which would otherwise treat .js as ESM and
// fail on `module.exports`). Minimal — just enough to build the wasm in CI.
emit(`tree-sitter/${langName}/package.json`,
  JSON.stringify({ name: `tree-sitter-${langName}`, version: '0.0.0', private: true }, null, 2));

// Monaco Monarch tokenizer (markup-aware: emits a tag/text/raw-text state machine).
emit(`${langName}.monarch.json`, JSON.stringify(generateMonarch(grammar), null, 2));

// Per-arm CST destructurers.
emit(`${langName}.cst-match.ts`, generateCstMatch(grammar));

function formatExpr(expr: RuleExpr): string {
  switch (expr.type) {
    case 'literal': return `'${expr.value}'`;
    case 'ref': return expr.name;
    case 'op': return 'op';
    case 'prefix': return 'prefix';
    case 'postfix': return 'postfix';
    case 'seq': return expr.items.map(formatExpr).join(' ');
    case 'alt': return expr.items.map(formatExpr).join(' | ');
    case 'quantifier': return `${formatExpr(expr.body)}${expr.kind}`;
    case 'group': return `(${formatExpr(expr.body)})`;
    case 'not': return `not(${formatExpr(expr.body)})`;
    case 'sameLine': return 'sameLine';
    case 'noCommentBefore': return 'noCommentBefore';
    case 'noMultilineFlowBefore': return 'noMultilineFlowBefore';
    case 'notLeftLeaf': return `notLeftLeaf(${expr.words.map(w => `'${w}'`).join(', ')})`;
    case 'sep': return `sep(${formatExpr(expr.element)}, '${expr.delimiter}')`;
  }
}

// JavaScriptReact (`.jsx`) — JavaScript + JSX.
//
// This file plays two roles, mirroring how javascript.ts is both the JS grammar AND
// the owner of the shared ECMAScript vocabulary that typescript.ts imports:
//   1. It is the `.jsx` GRAMMAR — `export default withJsx(javascript, …)`.
//   2. It owns the shared JSX LAYER (`withJsx`), which typescriptreact.ts imports to
//      build the `.tsx` grammar. So `typescriptreact → javascriptreact` for the JSX
//      layer parallels `typescript → javascript` for the base vocabulary.
//
// `withJsx(base, …)` turns ANY ECMAScript-family base grammar — javascript.ts or
// typescript.ts — into its React/JSX dialect WITHOUT re-declaring the base's rules,
// so each react grammar stays a one-liner and the conformance-proven base files are
// untouched. Why post-process the BUILT grammar instead of importing + extending the
// rule objects: combinator rules bind their sibling references by OBJECT IDENTITY at
// definition time, so a JSX-aware `Expr` cannot be spliced into a frozen base by
// reference (the base's `Block`→`Stmt`→`Expr` chain still points at the non-JSX
// `Expr`). The BUILT grammar references rules by NAME, so we patch at that level — the
// JSX rules reference `Expr`/`Type`/`Block` by name and resolve against whichever base
// they are merged into.
//
// The dialect is exactly the JSX delta JavaScript/TypeScript-to-JSX needs:
//   1. Prepend a `JSXElement` alternative to `Expr` (a NUD: a leading `<` at
//      expression-start is JSX — comparison `<` and generic-call `f<T>` are LEDs that
//      need a left operand, so they never fire at expression-start).
//   2. Drop the `<T>expr` prefix cast from `Expr` (forbidden in .tsx/.jsx — the leading
//      `<` is JSX; `as`/`satisfies` casts are unaffected). It is the only `Expr`
//      alternative that begins with a literal `<`, so it is removed by shape.
//   3. Add the JSX rules + the `/>` / `</` atomic tokens (placed before the regex token
//      so `</div>` lexes a close-tag, not a regex literal), and mark `>` / `}` as
//      division-context so a following `/` after a tag/container isn't a regex.
//
// Generic type-arguments on a tag (`<List<string>>`) are TypeScript-only, so the JSX
// rules include them only when the base has a `Type` rule (TS) and omit them for the
// type-free JavaScript base.

import { token, rule, defineGrammar, sameLine, sep, opt, many, alt, seq } from './src/api.ts';
import javascript, { Ident, Number_, String_ } from './javascript.ts';
import type { CstGrammar, RuleDecl, TokenDecl, RuleExpr } from './src/types.ts';

// `/>` (self-closing) and `</` (close-tag open) are atomic JSX punctuation tokens.
const JSXSelfClose = token(seq('/', '>'));
const JSXClose = token(seq('<', '/'));

// Build the JSX rule + token DECLARATIONS (serialized, name-referenced). The JSX
// rules reference `Expr`/`Type` via stub rules of those names, so once spliced into a
// base grammar the names resolve to the base's real `Expr`/`Type`. Run through
// defineGrammar purely to serialize; only the JSX entries are kept.
function buildJsxDecls(hasTypes: boolean): { rules: RuleDecl[]; tokens: TokenDecl[] } {
  const Expr = rule($ => [Ident]); // stub → supplies the name "Expr"
  const Type = rule($ => [Ident]); // stub → supplies the name "Type"
  // A dotted / namespaced / hyphenated tag or attribute name: `Foo`, `Foo.Bar`,
  // `svg:rect`, `data-id` (the lexer splits `data-id` into `Ident '-' Ident`).
  const nameTail = many(alt(['.', Ident], [':', Ident], [sameLine, '-', Ident]));
  const typeArgs = hasTypes ? [opt('<', sep(Type, ','), '>')] : [];

  const JSXTagName = rule($ => [[Ident, nameTail]]);
  const JSXAttrValue = rule($ => [String_, ['{', Expr, '}']]);
  const JSXAttr = rule($ => [
    ['{', '...', Expr, '}'],                       // spread attribute {...expr}
    [Ident, nameTail, opt('=', JSXAttrValue)],     // name (= value)?
  ]);
  const JSXContainer = rule($ => [['{', opt('...'), opt(Expr), '}']]);
  const JSXChild = rule($ => [
    JSXElement,
    JSXContainer,
    Ident, Number_, String_,                       // tokenizable text words
    alt(',', '.', ':', ';', '!', '?'),             // common sentence punctuation
  ]);
  const JSXElement = rule($ => [
    ['<', JSXTagName, ...typeArgs, many(JSXAttr), JSXSelfClose],
    ['<', JSXTagName, ...typeArgs, many(JSXAttr), '>', many(JSXChild), JSXClose, opt(JSXTagName), '>'],
    ['<', '>', many(JSXChild), JSXClose, '>'],      // fragment
  ]);

  const g = defineGrammar({
    name: 'jsx-decls',
    tokens: { Ident, Number: Number_, String: String_, JSXSelfClose, JSXClose },
    rules: { Expr, Type, JSXTagName, JSXAttrValue, JSXAttr, JSXContainer, JSXChild, JSXElement },
    entry: JSXElement,
  });
  const ruleNames = new Set(['JSXTagName', 'JSXAttrValue', 'JSXAttr', 'JSXContainer', 'JSXChild', 'JSXElement']);
  const tokNames = new Set(['JSXSelfClose', 'JSXClose']);
  return {
    rules: g.rules.filter(r => ruleNames.has(r.name)),
    tokens: g.tokens.filter(t => tokNames.has(t.name)),
  };
}

// Repository-key NAMING CONSTRAINT — the JSX delta. The base's `canonicalRepoNames`
// (`jsBaseCanonical`, owned by javascript.ts) is inherited through the `{ ...base }` spread
// below; this adds ONLY the JSX-key correspondences, so BOTH the `.jsx` and `.tsx` dialects
// (each built via `withJsx`) emit the official names natively. Monogram's JSX decomposition
// differs from the official's (it splits element/fragment/self-closing where the official splits
// tag-with/without-attributes), so MOST JSX keys are deliberately NOT mapped — only a genuine 1:1
// is aligned. `jsx-children`, `jsx-string-double-quoted`, `jsx-string-single-quoted` ALREADY match
// by name (gen-tm never clobbers an existing key, so listing them is unnecessary). Verified 1:1:
//   • `jsx-entities` ← `jsx-entity` — the JSX character-entity construct (`&amp;`/`&#65;`/`&#x41;`),
//     same emitted scopes (`constant.character.entity` + `punctuation.definition.entity`); the
//     official name is the plural wrapper, Monogram's is the single match rule. A pure rename.
// Deliberately NOT mapped (decompose/scope differently — a rename would NOT be a faithful
// projection, so it would mis-serve an `#include`): `jsx-evaluated-code` (Monogram's `jsx-expression`
// scopes the braces with `name`, the official scopes only the content with `contentName`, and embeds
// `$self` vs `#expression`), `jsx-tag-attributes` (Monogram's `jsx-attributes` is a bare wrapper; the
// official is a `meta.tag.attributes`-scoped begin/end region), and the whole `jsx-tag*` element
// family (a different structural split).
const JSX_CANONICAL: Record<string, string | string[]> = {
  'jsx-entities': 'jsx-entity',
};

const isLiteral = (e: RuleExpr, v: string): boolean => e.type === 'literal' && e.value === v;

/** Turn an ECMAScript-family base grammar into its React/JSX dialect. Imported by
 *  typescriptreact.ts. See the file header for why this post-processes the built grammar. */
export function withJsx(base: CstGrammar, opts: { name: string; scopeName: string }): CstGrammar {
  const hasTypes = base.rules.some(r => r.name === 'Type');
  const jsx = buildJsxDecls(hasTypes);

  // Patch Expr: prepend JSXElement, drop the literal-`<`-first cast alternative.
  const patched: RuleDecl[] = base.rules.map(r => {
    if (r.name !== 'Expr') return r;
    const alts = r.body.type === 'alt' ? r.body.items : [r.body];
    const kept = alts.filter(a => !(a.type === 'seq' && isLiteral(a.items[0], '<')));
    const jsxRef: RuleExpr = { type: 'ref', name: 'JSXElement' };
    return { ...r, body: { type: 'alt', items: [jsxRef, ...kept] } };
  });
  // The parser uses the LAST rule as the entry point, so splice the JSX rules in
  // BEFORE the base's entry rule rather than after it.
  const entry = patched[patched.length - 1];
  const rules: RuleDecl[] = [...patched.slice(0, -1), ...jsx.rules, entry];

  // Insert the JSX tokens immediately before the regex token (so `</`,`/>` lex
  // atomically) and extend its division-context with `>` / `}`.
  let placed = false;
  const tokens: TokenDecl[] = [];
  for (const t of base.tokens) {
    if (t.regexContext && !placed) {
      tokens.push(...jsx.tokens);
      placed = true;
      const dat = t.regexContext.divisionAfterTexts ?? [];
      const add = ['>', '}'].filter(x => !dat.includes(x));
      tokens.push({ ...t, regexContext: { ...t.regexContext, divisionAfterTexts: [...dat, ...add] } });
    } else {
      tokens.push(t);
    }
  }
  if (!placed) tokens.push(...jsx.tokens); // base has no regex token — just append

  // Inherit the base's canonical repo-key names (jsBaseCanonical for the JS base, the full TS map
  // for the TS base) and add the JSX delta, so both the `.jsx` and `.tsx` dialects emit the official
  // names natively. Pure DATA merge — gen-tm only looks them up, so the engine stays agnostic.
  return {
    ...base, name: opts.name, scopeName: opts.scopeName, rules, tokens,
    canonicalRepoNames: { ...base.canonicalRepoNames, ...JSX_CANONICAL },
  };
}

// The `.jsx` grammar: the JavaScript base + the JSX layer above.
export default withJsx(javascript, { name: 'javascriptreact', scopeName: 'source.js.jsx' });

// Build-time grammar transform implementing the ECMAScript [Await]/[Yield] grammar
// parameters by NAME-FORKING the body-reachable rule closure into context families.
//
// WHY a fork and not a runtime flag: Monogram's incremental adoption reuses a row iff
// its window (text + bars) replays identically — a row's parse must be a pure function
// of (window text, window bars) GIVEN ITS RULE. async/generator context flows from an
// ENCLOSING function OUTSIDE a row's window, so a runtime context flag read by core()
// but absent from the reuse key breaks that purity (a far `function`->`async function`
// edit, or even node surgery re-parsing a body statement with the ambient flag reset to
// its default, makes edit() diverge from a fresh parse). The fix that costs ZERO new
// reuse machinery: make the context part of the RULE IDENTITY. Every reuse predicate
// already keys on rowRule/rid (adoptSeek, runExtend, surgery's SURG_ELEM/RULE_FN_BY_ID),
// and the memo arrays are name-keyed, so an await-context Block is literally a different
// rule (Block$A) with its own rid and memo slot — a cross-family reuse is structurally
// UNREPRESENTABLE, not merely guarded. The window-replay theorem holds verbatim: the
// rule is part of the frame identity, never out-of-window text.
//
// HOW context boundaries are expressed: the grammar wraps each function/arrow/method/
// class BODY (and an async arm's params) in a context marker — awaitCtx / yieldCtx /
// asyncGenCtx for the operator contexts, resetCtx for the bodies that reset to none
// (a nested non-async function, a class body, a computed key, a field initializer).
// The markers are transparent `group` nodes carrying `ctxMode`; only this transform
// reads them. The fork is driven ENTIRELY by the markers — the reset boundary (open
// question #3) is explicit, not inferred.
//
// Forks collapse to their BASE rule for every DERIVED artifact via RuleDecl.canon: the
// emitted parser keeps the distinct name for memo/adoption identity but reports `canon`
// as the green-node rule name (so trees stay byte-identical to the base grammar), and
// the AST / TM / tree-sitter / cst-match generators skip forks (a fork's structure and
// scope are its base's).
import type { CstGrammar, RuleDecl, RuleExpr } from './types.ts';

type Family = 'await' | 'yield' | 'asyncgen';
const SUFFIX: Record<Family, string> = { await: '$A', yield: '$Y', asyncgen: '$AY' };
const RESERVED: Record<Family, string[]> = { await: ['await'], yield: ['yield'], asyncgen: ['await', 'yield'] };


export function withAwaitYield(grammar: CstGrammar): CstGrammar {
  const byName = new Map(grammar.rules.map(r => [r.name, r]));

  // ── 1. Per-family closure: which rules need an $F clone. A rule S is in closure[F]
  // if it is reachable, via in-family refs, from a subtree marked mode F — where a
  // nested marker of mode M re-roots the walk into family M (or plain, for reset). ──
  const closure: Record<Family, Set<string>> = { await: new Set(), yield: new Set(), asyncgen: new Set() };

  // Walk `expr` collecting the rule refs reachable WITHOUT crossing a ctx marker, and
  // recurse into nested markers under their own family. `intoFamily(name, F)` enrolls a
  // rule into closure[F] and (first time) walks its body under F.
  function walkExpr(expr: RuleExpr, fam: Family | null): void {
    if (!expr || typeof expr !== 'object') return;
    switch (expr.type) {
      case 'ref':
        if (fam && byName.has(expr.name)) intoFamily(expr.name, fam);
        return;
      case 'group':
        if (expr.ctxMode && expr.ctxMode !== 'reset') { walkExpr(expr.body, expr.ctxMode); return; }
        if (expr.ctxMode === 'reset') { walkExpr(expr.body, null); return; }   // plain family: no clone needed
        walkExpr(expr.body, fam); return;
      case 'seq': case 'alt': expr.items.forEach(i => walkExpr(i, fam)); return;
      case 'quantifier': walkExpr(expr.body, fam); return;
      case 'not': walkExpr(expr.body, fam); return;
      case 'sep': walkExpr(expr.element, fam); return;
      default: return;   // literal / zero-width markers
    }
  }
  function intoFamily(name: string, fam: Family): void {
    if (closure[fam].has(name)) return;
    closure[fam].add(name);
    const r = byName.get(name);
    if (r) walkExpr(r.body, fam);   // refs inside an enrolled rule stay in-family
  }
  // Seed: scan every BASE rule body for ctx markers (the function/arrow/method/class
  // body roots) and walk their contents under the marked family.
  for (const r of grammar.rules) walkExpr(r.body, null);

  // ── 2. Rewrite an expr for emission in family `fam` (null = plain/base): a ref to a
  // rule in closure[fam] becomes the $F clone; a nested ctx marker switches family;
  // a reset marker drops to plain; a GUARD_RULE ref takes the family-suffixed guard. ──
  function rewrite(expr: RuleExpr, fam: Family | null): RuleExpr {
    if (!expr || typeof expr !== 'object') return expr;
    switch (expr.type) {
      case 'ref': {
        if (fam && closure[fam].has(expr.name)) return { type: 'ref', name: expr.name + SUFFIX[fam] };
        return expr;
      }
      case 'group': {
        const inner = expr.ctxMode === 'reset' ? null : (expr.ctxMode ? expr.ctxMode : fam);
        const body = rewrite(expr.body, inner);
        // strip the ctxMode marker from the emitted grammar (it has done its routing
        // job); keep `suppress` (no-in context) and `capBelow` (assignment-level cap),
        // both still read by the parser engine. (tsRelaxed is gen-treesitter-only and the
        // post-fork grammar is the PARSER's, which uses `body` — so it is correctly dropped.)
        const g: RuleExpr = { type: 'group', body };
        if (expr.suppress !== undefined) g.suppress = expr.suppress;
        if (expr.capBelow !== undefined) g.capBelow = expr.capBelow;
        return g;
      }
      case 'seq': return { type: 'seq', items: expr.items.map(i => rewrite(i, fam)) };
      case 'alt': return { type: 'alt', items: expr.items.map(i => rewrite(i, fam)) };
      case 'quantifier': return { type: 'quantifier', body: rewrite(expr.body, fam), kind: expr.kind };
      case 'not': {
        // the bare-identifier reserved-word guard: inside a context family, also
        // forbid that family's keyword(s), so `await`/`yield` lose their identifier
        // reading (await with no operand then rejects — the prefix op needs one).
        const body = fam && expr.reservable ? addReserved(rewrite(expr.body, fam), RESERVED[fam]) : rewrite(expr.body, fam);
        return expr.reservable ? { type: 'not', body, reservable: true } : { type: 'not', body };
      }
      case 'sep': return { type: 'sep', element: rewrite(expr.element, fam), delimiter: expr.delimiter };
      default: return expr;
    }
  }

  // ── 3. The forked rules (appended AFTER the base rules so every existing rid =
  // rules.indexOf is unchanged and the entry rule stays last). ──
  const forks: RuleDecl[] = [];
  const families: Family[] = ['await', 'yield', 'asyncgen'];
  for (const fam of families) {
    const suf = SUFFIX[fam];
    for (const name of closure[fam]) {
      const base = byName.get(name)!;
      // rewrite reroutes in-family refs to $F and extends any reservable guard with
      // the family's context keyword (see the 'not' case in rewrite()).
      forks.push({ name: name + suf, body: rewrite(base.body, fam), flags: [...base.flags], canon: name });
    }
  }

  // ── 4. Rewrite the BASE rules in place: a base rule containing ctx markers must now
  // reference the $F clones at those roots (materialize the routing). Refs OUTSIDE any
  // marker stay plain. ──
  const baseRewritten: RuleDecl[] = grammar.rules.map(r => ({ ...r, body: rewrite(r.body, null) }));

  // Insert the forks BEFORE the entry rule (the last rule — findEntryRule reads
  // rules[length-1]) so the entry stays last. Existing rids shift only for the entry,
  // which is looked up by position consistently everywhere; forks (body-internal
  // rules) are never the entry.
  if (forks.length === 0) return { ...grammar, rules: baseRewritten };
  const entry = baseRewritten[baseRewritten.length - 1];
  return { ...grammar, rules: [...baseRewritten.slice(0, -1), ...forks, entry] };
}

// Collapse the [Await]/[Yield] forks back to the base grammar for the DERIVED-artifact
// generators (AST types / TM scopes / tree-sitter rules): drop every fork rule and
// rewrite any reference to a fork (the base async arm's rerouted Block$A, etc.) back to
// its base name. The result is structurally the pre-fork grammar, so those generators
// emit byte-identically. Identity (returns the same object) when nothing is forked.
export function dropForks(grammar: CstGrammar): CstGrammar {
  const canonOf = new Map<string, string>();
  for (const r of grammar.rules) if (r.canon) canonOf.set(r.name, r.canon);
  if (canonOf.size === 0) return grammar;
  const reref = (e: RuleExpr): RuleExpr => {
    if (!e || typeof e !== 'object') return e;
    switch (e.type) {
      case 'ref': return canonOf.has(e.name) ? { type: 'ref', name: canonOf.get(e.name)! } : e;
      case 'group': return { type: 'group', body: reref(e.body), ...(e.suppress !== undefined ? { suppress: e.suppress } : {}), ...(e.capBelow !== undefined ? { capBelow: e.capBelow } : {}) };
      case 'seq': return { type: 'seq', items: e.items.map(reref) };
      case 'alt': return { type: 'alt', items: e.items.map(reref) };
      case 'quantifier': return { type: 'quantifier', body: reref(e.body), kind: e.kind };
      case 'not': return { type: 'not', body: reref(e.body) };
      case 'sep': return { type: 'sep', element: reref(e.element), delimiter: e.delimiter };
      default: return e;
    }
  };
  return { ...grammar, rules: grammar.rules.filter(r => !r.canon).map(r => ({ ...r, body: reref(r.body) })) };
}

// Add `words` to the INNER body of a reservable guard's not(...): the body is the
// alt of forbidden literals (`alt('catch','class',…)`) or a single literal. Returns
// the extended alt; the caller wraps it back in the `not`.
function addReserved(inner: RuleExpr, words: string[]): RuleExpr {
  const lits = words.map((w): RuleExpr => ({ type: 'literal', value: w }));
  if (inner.type === 'alt') return { type: 'alt', items: [...inner.items, ...lits] };
  return { type: 'alt', items: [inner, ...lits] };
}
